-- Migration: ID Template Module (100% exact-copy template system)
-- Run this SQL to add template management for the ID editor.
-- Each template stores the uploaded FRONT and BACK design image (PNG/JPG),
-- plus a JSON list of data "zones" (coordinate boxes) drawn on top of the
-- exact image. Templates are active per department and automatically matched
-- when an admin creates an ID.
--
-- is_system = 1 marks the built-in "Original LSC Design" templates. These use
-- the CSS-based FrontCard/BackCard renderer (the exact original ID look) and
-- CANNOT be deleted or renamed by admins.

CREATE TABLE IF NOT EXISTS id_templates (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  name VARCHAR(150) NOT NULL,
  id_type ENUM('COLLEGE','JUNIOR_HIGH','SENIOR_HIGH') NOT NULL DEFAULT 'COLLEGE',
  front_image VARCHAR(255) NOT NULL DEFAULT '',
  back_image VARCHAR(255) DEFAULT '',
  fields_json LONGTEXT NULL,
  is_active TINYINT(1) NOT NULL DEFAULT 0,
  is_system TINYINT(1) NOT NULL DEFAULT 0,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  INDEX idx_id_type (id_type)
);

ALTER TABLE id_cards
  ADD COLUMN IF NOT EXISTS template_id INT UNSIGNED NULL DEFAULT NULL AFTER signatory_id;

/*
 * Seed the ORIGINAL LSC DESIGN as 3 protected system templates (one per dept).
 * These reproduce the exact built-in CSS FrontCard/BackCard look and are the
 * default templates. They cannot be deleted.
 *
 * Zone coordinates match the 321 x 506 CSS pixel layout of the original design:
 *   - photo:      top-left 128x160 frame
 *   - name band:  full-width band below photo row
 *   - student #:  bottom-front number area
 *   - back:       address / emergency / terms / school / signature blocks
 */
INSERT INTO id_templates (name, id_type, front_image, back_image, fields_json, is_active, is_system)
SELECT 'Original LSC Design', 'COLLEGE', '', '', '[{"key":"photo","label":"ID Photo","side":"front","x":16,"y":92,"w":128,"h":160,"fit":"cover","required":true},{"key":"student_name","label":"Student Name","side":"front","x":16,"y":330,"w":289,"h":46,"font_size":18,"font_weight":800,"font_family":"Oswald","transform":"uppercase","color":"#ffffff","align":"center"},{"key":"course","label":"College Course","side":"front","x":16,"y":376,"w":289,"h":22,"font_size":10,"font_weight":600,"font_family":"Montserrat","transform":"uppercase","color":"#ffffff","align":"center"},{"key":"student_number","label":"Student Number / ID Number","side":"front","x":16,"y":416,"w":289,"h":38,"font_size":16,"font_weight":700,"font_family":"Oswald","transform":"none","color":"#173f29","align":"center"},{"key":"address_line1","label":"Home Address (Line 1)","side":"back","x":18,"y":38,"w":285,"h":18,"font_size":10,"font_weight":400,"font_family":"Montserrat","transform":"none","color":"#000000","align":"left"},{"key":"address_line2","label":"Home Address (Line 2)","side":"back","x":18,"y":56,"w":285,"h":18,"font_size":10,"font_weight":400,"font_family":"Montserrat","transform":"none","color":"#000000","align":"left"},{"key":"emergency_contact","label":"Emergency Contact Person","side":"back","x":18,"y":108,"w":285,"h":18,"font_size":10,"font_weight":400,"font_family":"Montserrat","transform":"none","color":"#000000","align":"left"},{"key":"emergency_phone","label":"Emergency Contact Phone","side":"back","x":18,"y":126,"w":285,"h":18,"font_size":10,"font_weight":400,"font_family":"Montserrat","transform":"none","color":"#000000","align":"left"},{"key":"terms_title","label":"Terms & Conditions Title","side":"back","x":18,"y":168,"w":285,"h":18,"font_size":11,"font_weight":700,"font_family":"Montserrat","transform":"none","color":"#000000","align":"center"},{"key":"term_1","label":"Terms & Conditions (line 1)","side":"back","x":18,"y":190,"w":285,"h":16,"font_size":9,"font_weight":400,"font_family":"Montserrat","transform":"none","color":"#000000","align":"left","multiline":true},{"key":"term_2","label":"Terms & Conditions (line 2)","side":"back","x":18,"y":206,"w":285,"h":16,"font_size":9,"font_weight":400,"font_family":"Montserrat","transform":"none","color":"#000000","align":"left","multiline":true},{"key":"term_3","label":"Terms & Conditions (line 3)","side":"back","x":18,"y":222,"w":285,"h":16,"font_size":9,"font_weight":400,"font_family":"Montserrat","transform":"none","color":"#000000","align":"left","multiline":true},{"key":"institution_name","label":"Institution Name","side":"back","x":18,"y":268,"w":285,"h":18,"font_size":10,"font_weight":700,"font_family":"Montserrat","transform":"none","color":"#000000","align":"center"},{"key":"institution_address","label":"Institution Address","side":"back","x":18,"y":286,"w":285,"h":16,"font_size":9,"font_weight":400,"font_family":"Montserrat","transform":"none","color":"#000000","align":"center"},{"key":"mobile_no","label":"Mobile No.","side":"back","x":18,"y":302,"w":285,"h":16,"font_size":9,"font_weight":400,"font_family":"Montserrat","transform":"none","color":"#000000","align":"center"},{"key":"telephone_no","label":"Telephone No.","side":"back","x":18,"y":318,"w":285,"h":16,"font_size":9,"font_weight":400,"font_family":"Montserrat","transform":"none","color":"#000000","align":"center"},{"key":"email_address","label":"E-mail Address","side":"back","x":18,"y":334,"w":285,"h":16,"font_size":9,"font_weight":400,"font_family":"Montserrat","transform":"none","color":"#000000","align":"center"},{"key":"signatory_name","label":"Authorized Signatory Name","side":"back","x":18,"y":428,"w":285,"h":18,"font_size":10,"font_weight":700,"font_family":"Montserrat","transform":"none","color":"#000000","align":"center"},{"key":"signature","label":"Signature Image","side":"back","x":80,"y":380,"w":160,"h":48,"fit":"contain"}]', 1, 1
WHERE NOT EXISTS (SELECT 1 FROM id_templates WHERE is_system = 1 AND id_type = 'COLLEGE');


